    sim::EngineTestAccess_issue_1392_lusamine_chaotic_swell_tests::set_state(fixture.engine, exact_state());
    require(sim::EngineTestAccess_issue_1392_lusamine_chaotic_swell_tests::lusamine_targets(fixture.engine).empty(),
            "Chaotic Swell was promoted without a Rule Box Ability lock.");
