void test_k0_hidden_target_location_does_not_change_policy() {
  const sim::Scenario scenario{"issue-1549-k0", sim::DciProfile::StrictJit,
                               sim::LockMode::None, true, 4};
  const sim::DeckRecipe recipe = paired_hidden_target_recipe();
  std::mt19937_64 deck_rng{1549};
  std::mt19937_64 prize_rng{1549};
  sim::Engine deck_target_engine(scenario, recipe, deck_rng);
  sim::Engine prize_target_engine(scenario, recipe, prize_rng);
  seed_paired_hidden_target_state(deck_target_engine, true);
  seed_paired_hidden_target_state(prize_target_engine, false);

  // At K0, moving the only unseen legal target between the deck and unrevealed
  // Prizes cannot change the action policy. Both locations are still plausible
  // under fixed-list copy counts and identical public zones:
  // Mysterious Treasure: https://api.pokemontcg.io/v2/cards/sm6-113
  // Legacy Star: https://api.pokemontcg.io/v2/cards/swsh12-136
  // K0 contract: https://github.com/FlareZ123/pokemon-sims/blob/main/docs/POLICY_DECISIONS.md#k0-before-a-legal-inspection
  // Hidden-information specification: https://github.com/FlareZ123/pokemon-sims/blob/main/docs/MODEL_ASSUMPTIONS.md#policy-versus-future-card-oracle
  // Confirmed bug: https://github.com/FlareZ123/pokemon-sims/issues/1549
  const bool deck_target =
      sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::future_treasure_route_available(deck_target_engine);
  const bool prize_target =
      sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::future_treasure_route_available(prize_target_engine);
  if (!deck_target || !prize_target || deck_target != prize_target) {
    throw std::runtime_error(
        "K0 Legacy Star policy changed solely from hidden Treasure target location.");
  }
}

void test_k1_uses_exact_remaining_deck_target() {
  const sim::Scenario scenario{"issue-1549-k1", sim::DciProfile::StrictJit,
                               sim::LockMode::None, true, 4};
  const sim::DeckRecipe recipe = paired_hidden_target_recipe();
  std::mt19937_64 deck_rng{1549};
  std::mt19937_64 prize_rng{1549};
  sim::Engine deck_target_engine(scenario, recipe, deck_rng);
  sim::Engine prize_target_engine(scenario, recipe, prize_rng);
  seed_paired_hidden_target_state(deck_target_engine, true);
  seed_paired_hidden_target_state(prize_target_engine, false);
  sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::set_deck_seen(deck_target_engine);
  sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::set_deck_seen(prize_target_engine);

  // Once a legal deck search establishes K1, Mysterious Treasure target legality
  // uses the exact remaining deck. A target in Prizes is then known unavailable:
  // Mysterious Treasure: https://api.pokemontcg.io/v2/cards/sm6-113
  // K1 contract: https://github.com/FlareZ123/pokemon-sims/blob/main/docs/POLICY_DECISIONS.md#k1-after-a-legal-deck-or-prize-inspection
  // Confirmed bug: https://github.com/FlareZ123/pokemon-sims/issues/1549
  if (!sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::future_treasure_route_available(
          deck_target_engine) ||
      sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::future_treasure_route_available(
          prize_target_engine)) {
    throw std::runtime_error(
        "K1 Legacy Star policy did not use exact remaining-deck target availability.");
  }
}

void test_recovers_and_holds_treasure_for_t3_payload() {
  Fixture fixture(sim::LockMode::None);
  sim::Engine& engine = fixture.engine;
  seed_future_treasure_state(engine);
  sim::State& state = sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::state(engine);

  // Legacy Star may recover Mysterious Treasure. The held Grass is next turn's
  // manual attachment, and Treasure can then discard held Dragapult ex on the same
  // turn GGF becomes complete:
  // https://api.pokemontcg.io/v2/cards/swsh12-136
  // https://api.pokemontcg.io/v2/cards/sm6-113
  // https://api.pokemontcg.io/v2/cards/sv6-130
  // https://api.pokemontcg.io/v2/cards/swsh12-136
  // https://www.pokemon.com/us/pokemon-tcg/rules
  // https://github.com/FlareZ123/pokemon-sims/issues/1417
  const bool used = sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::use_legacy_star(engine);
  if (!used || !contains(state.hand, sim::Card::MysteriousTreasure)) {
    std::string cards;
    for (const sim::Card card : state.hand) {
      if (!cards.empty()) cards += ", ";
      cards += sim::name(card);
    }
    throw std::runtime_error("Legacy Star future Treasure failure: used=" +
                             std::string(used ? "true" : "false") +
                             "; hand=" + cards);
  }
  if (sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::play_mysterious_treasure(engine)) {
    throw std::runtime_error("Recovered Treasure must remain held during the Legacy Star turn.");
  }

  state.turn = 3;
  state.manual_energy_used = false;
  state.discarded_this_turn.clear();
  if (!sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::attach_manual(engine) ||
      !sim::EngineTestAccess_issue_1417_legacy_star_treasure_tests::play_mysterious_treasure(engine)) {
    throw std::runtime_error("The next-turn attachment and Treasure payload route should resolve.");
  }
  if (!state.active || state.active->grass != 2 || state.active->fire != 1 ||
      !contains(state.discarded_this_turn, sim::Card::Dragapult) ||
      !contains(state.hand, sim::Card::RegidragoV)) {
    throw std::runtime_error("The route must complete GGF, discard Dragapult ex on T3, and search legally.");
  }
}

