void test_route_gates() {
  const auto rejected = [](sim::State state, sim::Scenario selected,
                           const bool k1, const std::uint64_t seed,
                           const char* message) {
    std::mt19937_64 rng{seed};
    sim::Engine engine = make_engine(selected, rng);
    sim::EngineTestAccess_issue_1772_steven_t3_package_tests::set_state(engine, std::move(state), k1);
    expect(!sim::EngineTestAccess_issue_1772_steven_t3_package_tests::route_available(engine), message);
  };
  rejected(exact_t2_state(), scenario(), false, 17720,
           "The K1 route was admitted at K0.");
  rejected(exact_t2_state(), scenario(sim::LockMode::FullItem), true, 17721,
           "The route bypassed Item lock.");
  rejected(exact_t2_state(), scenario(sim::LockMode::FullRuleBoxAbility), true,
           17722, "The route bypassed Rule Box Ability lock.");
  {
    sim::State state = exact_t2_state();
    state.bench.front().entered_turn = state.turn;
    rejected(std::move(state), scenario(), true, 17723,
             "A same-turn Regidrago was admitted.");
  }
  {
    sim::State state = exact_t2_state();
    state.hand.push_back(sim::Card::Grass);
    rejected(std::move(state), scenario(), true, 17724,
             "The narrow route displaced a held-current-turn Energy line.");
  }
  for (const sim::Card missing : {sim::Card::Grass, sim::Card::Fire,
                                  sim::Card::LatiasEx, sim::Card::Dragapult}) {
    sim::State state = exact_t2_state();
    const auto found = std::find(state.deck.begin(), state.deck.end(), missing);
    if (found != state.deck.end()) state.deck.erase(found);
    if (missing == sim::Card::Grass) {
      const auto second = std::find(state.deck.begin(), state.deck.end(), missing);
      if (second != state.deck.end()) state.deck.erase(second);
    }
    rejected(std::move(state), scenario(), true,
             17730 + static_cast<std::uint64_t>(missing),
             "The route ignored a missing deck component.");
  }
}

