  sim::EngineTestAccess_issue_977_gladion_one_type_crispin_tests::set_state(fixture.engine, base_state());

  expect(sim::EngineTestAccess_issue_977_gladion_one_type_crispin_tests::play_gladion(fixture.engine),
         "Gladion should resolve in the blind critical state");
  const sim::State& after = sim::EngineTestAccess_issue_977_gladion_one_type_crispin_tests::state(fixture.engine);
  expect(contains(after.hand, sim::Card::Crispin),
         "the revealed one-type Crispin route should enter hand");
  expect(contains(after.prizes, sim::Card::RegidragoV),
         "the redundant Regidrago V should remain in Prizes");
