  assert(contains(state.hand, Card::Fire));
  assert(EngineTestAccess_legacy_star_evolution_incense_payload_tests::payload_ready(engine));
  assert(EngineTestAccess_legacy_star_evolution_incense_payload_tests::attach_manual(engine));
  EngineTestAccess_legacy_star_evolution_incense_payload_tests::record_ready(engine);

