  // known to have no effect and cannot be played, so both current resources stay held:
  // https://api.pokemontcg.io/v2/cards/sm6-113
  // https://api.pokemontcg.io/v2/cards/swsh1-179
  // https://compendium.pokegym.net/category/5-trainers/trainers-in-general/
  sim::DeckRecipe recipe = sim::baseline_recipe();
  std::mt19937_64 rng{232};
  sim::Engine engine(scenario, recipe, rng);
  sim::EngineTestAccess_mysterious_treasure_payload_continuation_tests::set_state(engine, std::move(state));
  sim::EngineTestAccess_mysterious_treasure_payload_continuation_tests::set_deck_seen(engine);

  expect(!sim::EngineTestAccess_mysterious_treasure_payload_continuation_tests::play_mysterious_treasure(engine),
         "Mysterious Treasure must not fetch the final deck card for a dead Quick Ball outlet.");
  const sim::State& result = sim::EngineTestAccess_mysterious_treasure_payload_continuation_tests::state(engine);
