  state.turn = 4;
  state.active = sim::Pokemon{sim::Card::LatiasEx, 0, 0, 0, sim::Tool::None};
  state.bench = {sim::Pokemon{sim::Card::RegidragoV, 1, 2, 0, sim::Tool::None}};
