  // https://github.com/FlareZ123/pokemon-sims/blob/main/src/trace_engine_v2/part_003.inc#L86-L104
  // https://github.com/FlareZ123/pokemon-sims/issues/837
  assert(sim::EngineTestAccess_roseanne_pokemon_communication_zone_tests::play_recovery(fixture.engine));
  assert_exact_recovery(sim::EngineTestAccess_roseanne_pokemon_communication_zone_tests::state(fixture.engine));
