  assert(!EngineTestAccess_stable_route_contract_tests::pay_tapu_retreat_to_ready_benched_vstar(engine));
  assert(state.active.has_value());
  assert(state.active->card == Card::TapuLeleGX);
  assert(!state.manual_energy_used);
