sim::State base_turn_one_state() {
  sim::State state;
  state.turn = 1;
  state.active = sim::Pokemon{sim::Card::LatiasEx, 0, 0, 0,
                              sim::Tool::None};
  state.bench = {sim::Pokemon{sim::Card::RegidragoV, 0, 0, 0,
                              sim::Tool::None}};
  state.hand = {sim::Card::TapuLeleGX};
  return state;
}

